// Deterministic date handling in your timezone + duplicate protection.
const cfg = $input.first().json;
const tz = cfg.timezone || 'UTC';
const parts = Object.fromEntries(
  new Intl.DateTimeFormat('en-CA', { timeZone: tz, year: 'numeric', month: '2-digit', day: '2-digit', weekday: 'long' })
    .formatToParts(new Date()).map(p => [p.type, p.value])
);
const dateIso = `${parts.year}-${parts.month}-${parts.day}`;

// Static data persists between PRODUCTION runs (active workflow), not manual test runs.
const staticData = $getWorkflowStaticData('global');
if (staticData.lastSentDate === dateIso) {
  return []; // today's message was already sent - stop quietly
}

return [{ json: {
  ...cfg,
  date_iso: dateIso,
  weekday: parts.weekday,
  day: Number(parts.day),
  month: Number(parts.month),
  year: Number(parts.year),
  is_school_day: !['Saturday', 'Sunday'].includes(parts.weekday)
} }];

// Clean the page to text and locate today's section with common date formats.
const ctx = $('Calculate Date and Avoid Duplicates').first().json;
const res = $input.first().json;
const html = typeof res.data === 'string' ? res.data : '';
if (!html) {
  return [{ json: { section: '', reason: res.error ? 'fetch_failed' : 'empty_page' } }];
}

const text = html
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<br\s*\/?>/gi, '\n')
  .replace(/<\/(p|div|li|h[1-6]|tr|section)>/gi, '\n')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&')
  .replace(/[ \t]+/g, ' ')
  .replace(/\n\s*\n+/g, '\n')
  .trim();

const { day: d, month: m, year: y } = ctx;
const pad = n => String(n).padStart(2, '0');
const months = ['January','February','March','April','May','June','July','August','September','October','November','December'];
const candidates = [
  `${d}.${m}.${y}`, `${pad(d)}.${pad(m)}.${y}`, `${y}-${pad(m)}-${pad(d)}`,
  `${d}/${m}/${y}`, `${pad(d)}/${pad(m)}/${y}`, `${m}/${d}/${y}`,
  `${months[m - 1]} ${d}`, `${d} ${months[m - 1]}`, `${d}.${m}.`
];
const esc = s => s.replace(/[.*+?^${}()|[\]\\\/]/g, '\\$&');

let idx = -1;
for (const c of candidates) {
  const match = new RegExp('(?<![0-9])' + esc(c), 'i').exec(text);
  if (match && (idx === -1 || match.index < idx)) idx = match.index;
}

let section;
if (idx !== -1) {
  section = text.slice(Math.max(0, idx - 20), idx + 3000);
} else {
  // No date found (e.g. pages listing weekdays only): let Gemini decide,
  // the validator still requires a verbatim date quote from this text.
  section = text.slice(0, 8000);
}
return [{ json: { section, date_located: idx !== -1 } }];

// Validate Gemini's answer against the source text. Never trust unverified AI output.
const section = $('Locate Today\'s Menu Section').first().json.section || '';
const raw = $input.first().json.text ?? $input.first().json.output ?? '';
let parsed;
try {
  parsed = JSON.parse(String(raw).replace(/```json|```/g, '').trim());
} catch (e) {
  return [{ json: { menu_status: 'unavailable', reason: 'gemini_output_not_json' } }];
}

const norm = s => String(s || '').toLowerCase().replace(/\s+/g, ' ').trim();
const quote = norm(parsed.date_text_seen);
if (!parsed.found || !quote || !norm(section).includes(quote)) {
  return [{ json: { menu_status: 'unavailable', reason: 'today_not_verified_on_page' } }];
}

const clean = v => (typeof v === 'string' && v.trim() && v.trim().length < 160) ? v.trim() : null;
const food = {
  breakfast: clean(parsed.breakfast),
  lunch: clean(parsed.lunch),
  vegetarian_lunch: clean(parsed.vegetarian_lunch),
  snack: clean(parsed.snack)
};
if (!food.breakfast && !food.lunch) {
  return [{ json: { menu_status: 'unavailable', reason: 'no_meals_found' } }];
}
return [{ json: { menu_status: 'ok', food } }];

// Deterministic weather summary + clothing advice for children who play outside.
const r = $input.first().json;
const out = { weather_status: 'unavailable', weather_line: null, clothing: null };
const h = r.hourly;

if (h && Array.isArray(h.time)) {
  // Daycare hours window (local time). Adjust START_HOUR / END_HOUR if needed.
  const START_HOUR = 7, END_HOUR = 17;
  const idx = h.time
    .map((t, i) => ({ hour: Number(String(t).slice(11, 13)), i }))
    .filter(x => x.hour >= START_HOUR && x.hour <= END_HOUR)
    .map(x => x.i);
  const pick = k => idx.map(i => h[k]?.[i]).filter(v => typeof v === 'number');

  const temps = pick('temperature_2m');
  const feels = pick('apparent_temperature');
  const rain = pick('precipitation');
  const wind = pick('wind_speed_10m');

  if (temps.length) {
    const tMin = Math.round(Math.min(...temps));
    const tMax = Math.round(Math.max(...temps));
    const fMin = Math.round(Math.min(...(feels.length ? feels : temps)));
    const windMax = wind.length ? Math.round(Math.max(...wind)) : 0;
    const precip = rain.reduce((a, b) => a + b, 0);
    const wet = precip >= 0.3;
    const snowy = wet && tMin <= 1;

    let line = tMin === tMax ? `${tMin}°C` : `${tMin}–${tMax}°C`;
    if (fMin < tMin - 2) line += ` (feels like ${fMin}°C)`;
    line += snowy ? `, snow likely (~${precip.toFixed(1)} mm)`
          : wet ? `, rain likely (~${precip.toFixed(1)} mm)`
          : ', no rain expected';
    if (windMax >= 8) line += `, windy (up to ${windMax} m/s)`;

    // Decision temperature = coldest "feels like" during the day
    const t = fMin;
    let base;
    if (t >= 18) base = 'T-shirt and shorts or a light dress; sun hat and sunscreen';
    else if (t >= 12) base = 'Long sleeves, long trousers and a light jacket';
    else if (t >= 5) base = 'Fleece layer under a jacket, long trousers, thin beanie';
    else if (t >= 0) base = 'Warm jacket over a fleece, beanie, gloves and warm shoes';
    else if (t >= -10) base = 'Winter overall with a wool base layer, winter boots, mittens and a warm hat';
    else base = 'Full winter gear: wool base layer, winter overall, balaclava, insulated mittens and boots';

    const extras = [];
    if (snowy) extras.push('waterproof outer layer and snow-proof mittens');
    else if (wet) extras.push('rain jacket, rain trousers and rubber boots');
    if (windMax >= 8 && t < 18) extras.push('windproof outer layer');

    out.weather_status = 'ok';
    out.weather_line = line;
    out.clothing = base + (extras.length ? '. Also: ' + extras.join(', ') : '');
  }
}
return [{ json: out }];

// Deterministic message assembly. No AI here, so the output is predictable.
const ctx = $('Calculate Date and Avoid Duplicates').first().json;
const dash = '—';

// Nodes on skipped branches cannot be read, so every lookup is guarded.
let menu = null;
try { menu = $('Validate Gemini Menu Output').first().json; } catch (e) {}
if (!menu) { try { menu = $('Handle Menu Fetch Error').first().json; } catch (e) {} }

let rows = [];
try { rows = $('Read Family Schedule from Sheets').all().map(i => i.json).filter(r => r && r.title); } catch (e) {}

const today = ctx.weekday.toLowerCase();
const items = rows.filter(r => {
  const date = String(r.date || '').trim();
  if (date) return date === ctx.date_iso;
  return String(r.weekday || '').split(',').map(s => s.trim().toLowerCase()).includes(today);
});

let wx = { weather_status: 'unavailable' };
try { wx = $('Generate Weather and Clothing Advice').first().json; } catch (e) {}

const parts = [`Good morning ☀️\n${ctx.weekday} ${ctx.date_iso}`];

if (ctx.is_school_day) {
  if (menu && menu.menu_status === 'ok') {
    const f = menu.food;
    let lunch = f.lunch || dash;
    if (f.vegetarian_lunch) lunch += ` (veg: ${f.vegetarian_lunch})`;
    parts.push(`🍽️ Food\nBreakfast: ${f.breakfast || dash}\nLunch: ${lunch}\nSnack: ${f.snack || dash}`);
  } else {
    parts.push(`🍽️ Food\nMenu could not be retrieved today – check ${ctx.menu_url}`);
  }
}

if (items.length) {
  parts.push('📅 Today\n' + items.map(r => '• ' + r.title + (r.details ? ` – ${r.details}` : '')).join('\n'));
} else if (ctx.is_school_day) {
  parts.push('📅 Today\nNothing special in the schedule');
}

if (wx.weather_status === 'ok') {
  parts.push(`🌤️ Weather\n${wx.weather_line}\n\n👕 Dress\n${wx.clothing}`);
} else {
  parts.push('🌤️ Weather\nForecast unavailable – check the window 🙂');
}

parts.push('Have a great day ❤️');
return [{ json: { message: parts.join('\n\n'), recipient: String(ctx.whatsapp_phone).replace(/[^0-9]/g, '') } }];

// Only a confirmed delivery marks today as done, so a failed send is retried next run.
const body = String($input.first().json.data ?? JSON.stringify($input.first().json));
const ok = /queued|sent/i.test(body) && !/error|invalid|not registered/i.test(body);
if (!ok) {
  throw new Error('WhatsApp delivery was not confirmed: ' + body.replace(/<[^>]+>/g, ' ').slice(0, 200));
}
const ctx = $('Calculate Date and Avoid Duplicates').first().json;
$getWorkflowStaticData('global').lastSentDate = ctx.date_iso;
return [{ json: { delivered: true, date: ctx.date_iso } }];
